(function initTheme() { const saved = localStorage.getItem('ems-theme') || 'light'; applyTheme(saved); })(); function applyTheme(theme) { document.documentElement.setAttribute('data-theme', theme); const icon = document.getElementById('themeIcon'); if (icon) { icon.className = theme === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-fill'; } } document.addEventListener('DOMContentLoaded', function () { document.querySelectorAll('#themeToggle').forEach(btn => { btn.addEventListener('click', function () { const current = document.documentElement.getAttribute('data-theme'); const next = current === 'dark' ? 'light' : 'dark'; applyTheme(next); localStorage.setItem('ems-theme', next); }); }); const sidebarToggle = document.getElementById('sidebarToggle'); const sidebar = document.getElementById('sidebar'); if (sidebarToggle && sidebar) { sidebarToggle.addEventListener('click', function () { sidebar.classList.toggle('open'); }); document.addEventListener('click', function (e) { if (!sidebar.contains(e.target) && !sidebarToggle.contains(e.target)) { sidebar.classList.remove('open'); } }); } const spinner = document.getElementById('spinnerOverlay'); document.querySelectorAll('a[href]').forEach(link => { const href = link.getAttribute('href'); if (href && !href.startsWith('#') && !href.startsWith('javascript') && href !== '') { link.addEventListener('click', function () { if (!link.target || link.target === '_self') { showSpinner(); } }); } }); document.querySelectorAll('form').forEach(form => { form.addEventListener('submit', function () { showSpinner(); }); }); window.addEventListener('load', hideSpinner); document.querySelectorAll('.alert-custom').forEach(el => { setTimeout(() => { el.style.transition = 'opacity 0.5s'; el.style.opacity = '0'; setTimeout(() => el.remove(), 500); }, 4000); }); document.querySelectorAll('.stat-card').forEach((card, i) => { card.style.opacity = '0'; card.style.transform = 'translateY(16px)'; setTimeout(() => { card.style.transition = 'opacity 0.4s ease, transform 0.4s ease'; card.style.opacity = '1'; card.style.transform = 'translateY(0)'; }, 80 * i); }); document.querySelectorAll('.table-custom tbody tr').forEach((row, i) => { row.style.opacity = '0'; setTimeout(() => { row.style.transition = 'opacity 0.3s ease'; row.style.opacity = '1'; }, 40 * i); }); }); function showSpinner() { const s = document.getElementById('spinnerOverlay'); if (s) s.classList.add('active'); } function hideSpinner() { const s = document.getElementById('spinnerOverlay'); if (s) s.classList.remove('active'); }